mapper.select:
SELECT s.id, s.user_id, u.name AS cashier_name, s.total_amount, s.real_amount, s.change_amount, IFNULL(s.order_num, CONCAT('SO', LPAD(s.id, 8, '0'))) AS order_num, s.create_time, IFNULL(srs.return_status, 0) AS return_status, s.payment_method, s.status FROM sales s LEFT JOIN user u ON s.user_id = u.id LEFT JOIN ( SELECT sales_id, CASE WHEN SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END) > 0 THEN 1 WHEN SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) > 0 THEN 2 ELSE 0 END AS return_status FROM sales_return WHERE IFNULL(type, 1) = 1 GROUP BY sales_id ) srs ON s.id = srs.sales_id
AND (s.order_num LIKE CONCAT('%', #{orderNum}, '%') OR CONCAT('SO', LPAD(s.id, 8, '0')) LIKE CONCAT('%', #{orderNum}, '%'))
AND s.create_time >= #{startDate}
AND s.create_time <= #{endDate}
AND s.user_id = #{userId}
ORDER BY s.create_time DESC

SELECT
    COUNT(*) AS cnt,
    IFNULL(SUM(s.total_amount), 0) AS total_amount,
    IFNULL(SUM(s.real_amount), 0) AS real_amount
FROM sales s


        AND (s.order_num LIKE CONCAT('%', #{orderNum}, '%')
             OR CONCAT('SO', LPAD(s.id, 8, '0')) LIKE CONCAT('%', #{orderNum}, '%'))


        AND s.create_time >= #{startDate}


        AND s.create_time <= #{endDate}


        AND s.user_id = #{userId}

SELECT
    COUNT(*) AS returnCount,
    IFNULL(SUM(sr.total_refund), 0) AS returnDueAmount,
    IFNULL(SUM(CASE WHEN sr.status = 1 THEN sr.total_refund ELSE 0 END), 0) AS returnPaidAmount
FROM sales_return sr


        AND sr.create_time >= #{startDate}


        AND sr.create_time <= #{endDate}


        AND sr.user_id = #{userId}

SELECT g.id AS goodsId, g.name AS goodsName, IFNULL(SUM(sd.count), 0) AS totalQuantity, IFNULL(SUM(sd.subtotal), 0) AS totalAmount FROM sales_detail sd INNER JOIN sales s ON sd.sales_id = s.id INNER JOIN goods g ON sd.goods_id = g.id
AND s.create_time >= #{startDate}
AND s.create_time <= #{endDate}
AND s.user_id = #{userId}
GROUP BY g.id, g.name ORDER BY totalAmount DESC

SELECT g.id AS goodsId, g.name AS goodsName, sr.type AS type, IFNULL(SUM(srd.return_count), 0) AS totalQuantity, IFNULL(SUM(srd.subtotal), 0) AS totalAmount FROM sales_return_detail srd INNER JOIN sales_return sr ON srd.return_id = sr.id INNER JOIN goods g ON srd.goods_id = g.id
AND sr.create_time >= #{startDate}
AND sr.create_time <= #{endDate}
AND sr.user_id = #{userId}
GROUP BY g.id, g.name, sr.type ORDER BY totalAmount DESC
